import{_ as e,o as l,c as r,a2 as i}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"裸机云重装系统指南","description":"","frontmatter":{"title":"裸机云重装系统指南"},"headers":[],"relativePath":"ops-knowledge-base/baremetal/reinstall-os-guide.md","filePath":"ops-knowledge-base/baremetal/reinstall-os-guide.md","lastUpdated":1788259091000}'),t={name:"ops-knowledge-base/baremetal/reinstall-os-guide.md"};function o(h,a,n,s,p,d){return l(),r("div",null,[...a[0]||(a[0]=[i('<h2 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to &quot;用途&quot;">​</a></h2><p>本文档介绍如何通过裸机云控制台重装服务器操作系统，包括系统选择、登录方式设置、数据保留规则及相关注意事项，帮助您顺利完成系统重装。</p><p><strong>适用产品：</strong> 裸机云（Bare Metal Cloud）</p><hr><h2 id="一、重装系统前须知" tabindex="-1">一、重装系统前须知 <a class="header-anchor" href="#一、重装系统前须知" aria-label="Permalink to &quot;一、重装系统前须知&quot;">​</a></h2><p>重装系统前，请务必了解以下事项：</p><ul><li>重装系统将重新安装操作系统，并<strong>格式化系统盘</strong>。</li><li>如服务器配置了<strong>数据盘</strong>，重装时<strong>仅格式化系统盘，数据盘不会被格式化，数据将保留</strong>。</li><li><strong>重装完成后，数据盘不会自动挂载，需要手动重新挂载后方可访问数据。</strong></li><li>重装系统将导致当前实例下<strong>所有历史快照失效并自动删除</strong>，且无法恢复。</li><li>创建实例时填写的**自定义脚本（Custom Script）**将在重装时自动执行，不支持重新输入或修改。</li><li>为避免数据丢失，建议提前备份重要数据。</li></ul><hr><h2 id="二、重装系统操作步骤" tabindex="-1">二、重装系统操作步骤 <a class="header-anchor" href="#二、重装系统操作步骤" aria-label="Permalink to &quot;二、重装系统操作步骤&quot;">​</a></h2><ol><li>登录 <strong>Raksmart 客户后台</strong>。</li><li>进入 <strong>产品管理</strong> → <strong>裸机云</strong>。</li><li>选择需要管理的服务器。</li><li>点击进入 <strong>管理</strong> 页面。</li><li>点击 <strong>重装系统</strong>。</li></ol><p>系统将弹出重装系统配置窗口。</p><hr><h2 id="三、配置重装参数" tabindex="-1">三、配置重装参数 <a class="header-anchor" href="#三、配置重装参数" aria-label="Permalink to &quot;三、配置重装参数&quot;">​</a></h2><h2 id="_1、选择操作系统" tabindex="-1">1、选择操作系统 <a class="header-anchor" href="#_1、选择操作系统" aria-label="Permalink to &quot;1、选择操作系统&quot;">​</a></h2><p>在操作系统列表中选择需要安装的系统版本。</p><p>支持安装的系统以控制台实际显示为准，例如：</p><ul><li>CentOS</li><li>Ubuntu</li><li>Debian</li><li>Windows Server</li></ul><hr><h2 id="_2、选择登录方式" tabindex="-1">2、选择登录方式 <a class="header-anchor" href="#_2、选择登录方式" aria-label="Permalink to &quot;2、选择登录方式&quot;">​</a></h2><p>系统提供以下两种登录方式。</p><h3 id="密码登录-password" tabindex="-1">密码登录（Password） <a class="header-anchor" href="#密码登录-password" aria-label="Permalink to &quot;密码登录（Password）&quot;">​</a></h3><p>选择密码登录后，可设置服务器登录密码。</p><p>支持：</p><ul><li>系统随机生成密码；</li><li>自定义登录密码。</li></ul><hr><h3 id="ssh-公钥登录-ssh-key" tabindex="-1">SSH 公钥登录（SSH Key） <a class="header-anchor" href="#ssh-公钥登录-ssh-key" aria-label="Permalink to &quot;SSH 公钥登录（SSH Key）&quot;">​</a></h3><p>Linux 系统支持使用 SSH 公钥登录。</p><p>选择该方式后，需要从已创建的 SSH 公钥列表中选择对应公钥。</p><p>如尚未创建 SSH 公钥，请先完成公钥添加。</p><blockquote><p><strong>详细操作请参考：《<a href="https://billing.raksmart.com/whmcs/index.php?rp=%2Fknowledgebase%2F989%2FSSH-KEY-%E7%AE%A1%E7%90%86.html&amp;language=chinese-cn" target="_blank" rel="noreferrer">SSH 公钥管理指南</a>》</strong></p></blockquote><hr><h2 id="_3、设置-ssh-端口" tabindex="-1">3、设置 SSH 端口 <a class="header-anchor" href="#_3、设置-ssh-端口" aria-label="Permalink to &quot;3、设置 SSH 端口&quot;">​</a></h2><p>Linux 系统支持设置 SSH 登录端口。</p><p>可选择：</p><ul><li>系统随机生成端口；</li><li>自定义 SSH 端口。</li></ul><blockquote><p><strong>建议：</strong></p><p>如修改默认 SSH 端口，请确保安全组及系统防火墙已放行对应端口，否则可能导致 SSH 无法连接。</p></blockquote><hr><h2 id="四、开始重装系统" tabindex="-1">四、开始重装系统 <a class="header-anchor" href="#四、开始重装系统" aria-label="Permalink to &quot;四、开始重装系统&quot;">​</a></h2><p>确认配置无误后，点击确认开始重装。</p><p>系统将自动完成以下操作：</p><ul><li>格式化系统盘；</li><li>安装新的操作系统；</li><li>配置登录方式；</li><li>设置登录密码或 SSH 公钥；</li><li>配置 SSH 登录端口（Linux）。</li></ul><p>系统安装完成后，即可使用新的登录信息连接服务器。</p><hr><h2 id="五、磁盘及数据说明" tabindex="-1">五、磁盘及数据说明 <a class="header-anchor" href="#五、磁盘及数据说明" aria-label="Permalink to &quot;五、磁盘及数据说明&quot;">​</a></h2><h2 id="系统盘" tabindex="-1">系统盘 <a class="header-anchor" href="#系统盘" aria-label="Permalink to &quot;系统盘&quot;">​</a></h2><p>重装系统时，系统盘将被格式化，并重新安装操作系统。</p><p>系统盘中的所有数据将被清除。</p><hr><h2 id="数据盘" tabindex="-1">数据盘 <a class="header-anchor" href="#数据盘" aria-label="Permalink to &quot;数据盘&quot;">​</a></h2><p>如果服务器配置了独立数据盘：</p><ul><li>重装系统时不会格式化数据盘；</li><li>数据盘中的数据将保留；</li><li>重装完成后，数据盘不会自动挂载。</li></ul><p>请登录服务器后，根据操作系统完成数据盘挂载，即可继续访问数据。</p><hr><h2 id="磁盘分区说明" tabindex="-1">磁盘分区说明 <a class="header-anchor" href="#磁盘分区说明" aria-label="Permalink to &quot;磁盘分区说明&quot;">​</a></h2><p>重装系统过程中，不支持重新调整磁盘分区。</p><p>对于已配置系统盘和数据盘的服务器：</p><ul><li>系统盘与数据盘保持原有结构；</li><li>不支持将系统盘与数据盘合并使用；</li><li>如需重新规划磁盘结构，建议提前做好数据备份，并根据实际需求重新部署服务器。</li></ul><hr><h2 id="六、其他说明" tabindex="-1">六、其他说明 <a class="header-anchor" href="#六、其他说明" aria-label="Permalink to &quot;六、其他说明&quot;">​</a></h2><h2 id="自定义脚本" tabindex="-1">自定义脚本 <a class="header-anchor" href="#自定义脚本" aria-label="Permalink to &quot;自定义脚本&quot;">​</a></h2><p>如果服务器创建实例时配置了<strong>自定义脚本（Custom Script）</strong>：</p><ul><li>重装系统后，将自动沿用创建实例时填写的自定义脚本；</li><li>不支持重新输入或修改自定义脚本。</li></ul><hr><h2 id="快照" tabindex="-1">快照 <a class="header-anchor" href="#快照" aria-label="Permalink to &quot;快照&quot;">​</a></h2><p>执行重装系统后：</p><ul><li>当前实例下所有历史快照将自动失效；</li><li>系统将自动删除所有历史快照；</li><li>删除后的快照无法恢复。</li></ul><p>如快照中保存有重要数据，请提前完成数据备份。</p><hr><h2 id="七、重装完成后建议检查" tabindex="-1">七、重装完成后建议检查 <a class="header-anchor" href="#七、重装完成后建议检查" aria-label="Permalink to &quot;七、重装完成后建议检查&quot;">​</a></h2><p>完成系统安装后，建议确认以下内容：</p><p>✅ 已使用新的登录信息成功登录服务器；</p><p>✅ 操作系统安装正确；</p><p>✅ Linux 系统可正常通过 SSH 登录；</p><p>✅ Windows 系统可正常通过远程桌面（RDP）登录；</p><p>✅ 如存在数据盘，已完成数据盘挂载；</p><p>✅ 业务数据及应用程序恢复正常运行。</p><hr><h2 id="八、常见问题" tabindex="-1">八、常见问题 <a class="header-anchor" href="#八、常见问题" aria-label="Permalink to &quot;八、常见问题&quot;">​</a></h2><h3 id="q1-重装系统会删除哪些数据" tabindex="-1">Q1：重装系统会删除哪些数据？ <a class="header-anchor" href="#q1-重装系统会删除哪些数据" aria-label="Permalink to &quot;Q1：重装系统会删除哪些数据？&quot;">​</a></h3><p>重装系统仅会格式化系统盘。</p><p>如果服务器配置了独立数据盘，则数据盘不会被格式化，数据仍会保留。</p><hr><h3 id="q2-为什么重装完成后看不到数据盘" tabindex="-1">Q2：为什么重装完成后看不到数据盘？ <a class="header-anchor" href="#q2-为什么重装完成后看不到数据盘" aria-label="Permalink to &quot;Q2：为什么重装完成后看不到数据盘？&quot;">​</a></h3><p>数据盘并未丢失。</p><p>重装系统完成后，数据盘不会自动挂载，因此需要登录服务器后手动完成挂载，挂载完成后即可正常访问数据。</p><hr><h3 id="q3-可以自定义登录密码吗" tabindex="-1">Q3：可以自定义登录密码吗？ <a class="header-anchor" href="#q3-可以自定义登录密码吗" aria-label="Permalink to &quot;Q3：可以自定义登录密码吗？&quot;">​</a></h3><p>可以。</p><p>选择<strong>密码登录</strong>方式时，可使用系统随机生成的密码，也可以自行设置登录密码。</p><hr><h3 id="q4-什么时候建议使用-ssh-公钥登录" tabindex="-1">Q4：什么时候建议使用 SSH 公钥登录？ <a class="header-anchor" href="#q4-什么时候建议使用-ssh-公钥登录" aria-label="Permalink to &quot;Q4：什么时候建议使用 SSH 公钥登录？&quot;">​</a></h3><p>建议 Linux 用户优先使用 SSH 公钥登录。</p><p>相比密码登录，SSH 公钥认证安全性更高，可有效降低密码泄露及暴力破解风险。</p><p>如需使用 SSH 公钥，请先在控制台添加 SSH 公钥。</p><hr><h3 id="q5-重装系统后-自定义脚本会重新执行吗" tabindex="-1">Q5：重装系统后，自定义脚本会重新执行吗？ <a class="header-anchor" href="#q5-重装系统后-自定义脚本会重新执行吗" aria-label="Permalink to &quot;Q5：重装系统后，自定义脚本会重新执行吗？&quot;">​</a></h3><p>会。</p><p>系统将自动沿用实例创建时配置的自定义脚本，不支持重新输入或修改。</p><hr><h3 id="q6-重装系统后-历史快照还能恢复吗" tabindex="-1">Q6：重装系统后，历史快照还能恢复吗？ <a class="header-anchor" href="#q6-重装系统后-历史快照还能恢复吗" aria-label="Permalink to &quot;Q6：重装系统后，历史快照还能恢复吗？&quot;">​</a></h3><p>不能。</p><p>重装系统会导致当前实例下所有历史快照自动删除，删除后无法恢复。</p><hr><h3 id="q7-重装系统时可以重新调整磁盘分区吗" tabindex="-1">Q7：重装系统时可以重新调整磁盘分区吗？ <a class="header-anchor" href="#q7-重装系统时可以重新调整磁盘分区吗" aria-label="Permalink to &quot;Q7：重装系统时可以重新调整磁盘分区吗？&quot;">​</a></h3><p>不可以。</p><p>重装过程中不支持重新调整磁盘分区，系统盘与数据盘将保持原有结构，不支持合并使用。</p><hr><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>⚠️ 重装系统前，请务必备份重要数据。</p><p>⚠️ 重装系统仅格式化系统盘，数据盘默认保留，但需在重装完成后手动重新挂载。</p><p>⚠️ 重装系统将导致当前实例下所有历史快照自动删除，删除后无法恢复。</p><p>⚠️ 重装过程中不支持重新调整磁盘分区，系统盘与数据盘将保持原有结构。</p><p>⚠️ 如修改 SSH 端口，请确认安全组及系统防火墙已放行对应端口。</p><p>⚠️ 创建实例时配置的自定义脚本将在重装过程中自动执行，不支持重新输入或修改。</p><hr>',115)])])}const q=e(t,[["render",o]]);export{c as __pageData,q as default};
